CREATE TABLE IF NOT EXISTS tenant_settings (organization_id TEXT NOT NULL PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE, suite_id TEXT NOT NULL, display_name TEXT NOT NULL, logo_url TEXT, primary_color TEXT NOT NULL DEFAULT '#4768ee', secondary_color TEXT NOT NULL DEFAULT '#8760f4', timezone TEXT NOT NULL DEFAULT 'America/Mexico_City', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tenant_tools (organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, tool_id TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)), PRIMARY KEY(organization_id,tool_id));
CREATE TABLE IF NOT EXISTS tenant_clients (id TEXT NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, email TEXT, phone TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(organization_id,id));
CREATE INDEX IF NOT EXISTS idx_tenant_clients_org ON tenant_clients(organization_id);
CREATE TABLE IF NOT EXISTS tenant_catalog_items (id TEXT NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, price_cents INTEGER CHECK(price_cents >= 0), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), PRIMARY KEY(organization_id,id));
CREATE TABLE IF NOT EXISTS tenant_appointments (id TEXT NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, client_id TEXT, title TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'scheduled', PRIMARY KEY(organization_id,id), FOREIGN KEY(organization_id,client_id) REFERENCES tenant_clients(organization_id,id));
CREATE INDEX IF NOT EXISTS idx_tenant_appointments_date ON tenant_appointments(organization_id,starts_at);
CREATE TABLE IF NOT EXISTS tenant_orders (id TEXT NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'draft', total_cents INTEGER NOT NULL DEFAULT 0 CHECK(total_cents >= 0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(organization_id,id));
CREATE TABLE IF NOT EXISTS tenant_service_requests (id TEXT NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, service_type TEXT NOT NULL, brief TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(organization_id,id));
CREATE INDEX IF NOT EXISTS idx_tenant_requests ON tenant_service_requests(organization_id,status);